HOT = {"item_42": 100}   # product -> number of salts

def add_view(pid):
    n = HOT.get(pid)
    if n:
        db.incr(f"views:{pid}#{random.randrange(n):02d}")
    else:
        db.incr(f"views:{pid}")

def get_views(pid):
    n = HOT.get(pid)
    if n:
        return sum(db.get(f"views:{pid}#{s:02d}", 0) for s in range(n))
    return db.get(f"views:{pid}", 0)
